targets.rawSql:
with explorers as (
  select distinct session_id from website_event
  where website_id = '$site' and url_path like '/explore%' and $__timeFilter(created_at)
),
interacted as (
  select distinct session_id from website_event
  where website_id = '$site' and event_name in ('item-click','explore-depth') and $__timeFilter(created_at)
)
select
  case when (select count(*) from explorers) = 0 then 0
       else (select count(*)::numeric from explorers e join interacted i using (session_id))
            / (select count(*) from explorers) end as "exploration rate";
